import{_ as a,W as o,s as u,u as d,I as t,ah as l,w as i,Z as s,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const f=JSON.parse('{"title":"在 Linux 上使用 WineZGUI 运行 Windows 应用和游戏 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 WineZGUI 运行 Windows 应用和游戏 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 WineZGUI 运行 Windows 应用和游戏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 WineZGUI 运行 Windows 应用和游戏 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220610 Run Windows Apps And Games Using WineZGUI On Linux","title":"在 Linux 上使用 WineZGUI 运行 Windows 应用和游戏","tag":"202206"},"relativePath":"202206/20220610 Run Windows Apps And Games Using WineZGUI On Linux.md","filePath":"[post].md"}'),r={name:"202206/20220610 Run Windows Apps And Games Using WineZGUI On Linux.md"};function g(W,n,h,m,x,I){const e=o("Link");return d(),u("div",null,[n[29]||(n[29]=t("h1",{id:"在-linux-上使用-winezgui-运行-windows-应用和游戏",tabindex:"-1"},[i("在 Linux 上使用 WineZGUI 运行 Windows 应用和游戏 "),t("a",{class:"header-anchor",href:"#在-linux-上使用-winezgui-运行-windows-应用和游戏","aria-label":"Permalink to 在 Linux 上使用 WineZGUI 运行 Windows 应用和游戏"},"​")],-1)),n[30]||(n[30]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/22/160322tds2ut05d8jqdlzz.jpg",alt:""})],-1)),n[31]||(n[31]=t("blockquote",null,[t("p",null,"WineZGUI - 一个使用 Zenity 的 Wine GUI 前台")],-1)),t("p",null,[n[2]||(n[2]=i("不久前，我们写了关于 ")),s(e,{href:"https://ostechnix.com/run-windows-software-on-linux-with-bottles/"},{default:p(()=>n[0]||(n[0]=[i("Bottles")])),_:1}),n[3]||(n[3]=i(" 的文章，这是一个开源的图形应用，可以在 Linux 操作系统上轻松运行 Windows 软件和游戏。今天，我们将讨论一个类似的有趣项目。向 ")),n[4]||(n[4]=t("strong",null,"WineZGUI",-1)),n[5]||(n[5]=i(" 打个招呼，它是一个 Wine GUI 前台，可以 ")),s(e,{href:"https://ostechnix.com/run-windows-games-softwares-ubuntu-16-04/"},{default:p(()=>n[1]||(n[1]=[i("在 Linux 上用 Wine 运行 Windows 应用和游戏")])),_:1}),n[6]||(n[6]=i("。"))]),n[32]||(n[32]=l('<h3 id="什么是-winezgui" tabindex="-1">什么是 WineZGUI？ <a class="header-anchor" href="#什么是-winezgui" aria-label="Permalink to 什么是 WineZGUI？">​</a></h3><p>WineZGUI 是一个 Bash 脚本的集合，它允许你轻松地管理 Wine 前缀，并在 Linux 上使用 <strong>Zenity</strong> 提供更轻松的 Wine 游戏体验。</p><p>（LCTT 译注：Wine 前缀是一个特殊文件夹，Wine 在其中放置所有 Wine 特定的文件，安装 Windows 程序、库和注册表代码，以及用户首选项。）</p><p>使用 WineZGUI，我们可以直接从文件管理器中启动 Windows EXE 文件或游戏，而无需安装它们。</p><p>WineZGUI 为每个应用或游戏创建快捷方式，以便于访问，同时也为每个 EXE 二进制文件创建单独的前缀。</p><p>当你用 WineZGUI 启动一个 Windows EXE 文件时，它会提示你是否使用默认的 Wine 前缀或创建一个新的前缀。默认的前缀是 <code>~/.local/share/winezgui/default</code>。</p><p>如果你选择为 Windows 二进制文件（EXE）创建一个新的前缀，WineZGUI 将尝试从 EXE 文件中提取产品名称和图标，并创建一个桌面快捷方式。</p><p>当你以后启动相同的二进制文件（EXE）时，它将建议你用先前的相关前缀来运行它。</p><p>说得通俗一点，WineZGUI 只是一个用于官方原始 Wine 的简单 GUI。当我们启动一个 EXE 来玩游戏时，Wine 前缀的设置是自动的。</p><p>你只需打开一个 EXE，它就会创建一个前缀和一个桌面快捷方式，并从该 EXE 中提取名称和图标。</p><p>它使用 <code>exiftool</code> 和 <code>icotool</code> 工具来分别提取名称和图标。你可以通过现有的前缀打开一个 EXE 来启动该游戏，或者使用桌面快捷方式。</p><p>WineZGUI 是一个在 GitHub 上免费托管的 shell 脚本。你可以抓取源代码，改进它，修复错误和增加功能。</p><h3 id="bottles-vs-winezgui" tabindex="-1">Bottles Vs WineZGUI <a class="header-anchor" href="#bottles-vs-winezgui" aria-label="Permalink to Bottles Vs WineZGUI">​</a></h3><p>你可能想知道 WineZGUI 与 Bottles 相比如何。但这些应用之间有一个微妙的区别。</p><p><strong>Bottles 是面向前缀的</strong>和<strong>面向运行器的</strong>。意思是：Bottles 首先创建一个前缀，然后使用不同的 EXE 文件。Bottles 不会记住 EXE 的前缀。Bottles 使用不同的运行器。</p><p><strong>WineZGUI 是面向 EXE 的</strong>。它使用 EXE 并只为该 EXE 创建一个前缀。下次我们打开一个 EXE 时，它将询问是否用现有的 EXE 前缀启动。</p>',16)),t("p",null,[n[8]||(n[8]=i("WineZGUI 不提供像 Bottles 或 ")),s(e,{href:"https://ostechnix.com/manage-games-using-lutris-linux/"},{default:p(()=>n[7]||(n[7]=[i("lutris")])),_:1}),n[9]||(n[9]=i(" 那样的高级功能，如运行程序、在线安装程序等。"))]),n[33]||(n[33]=l(`<h3 id="如何在-linux-中安装-winezgui" tabindex="-1">如何在 Linux 中安装 WineZGUI <a class="header-anchor" href="#如何在-linux-中安装-winezgui" aria-label="Permalink to 如何在 Linux 中安装 WineZGUI">​</a></h3><p>确保你已经安装了 WineZGUI 的必要先决条件。</p><p>Debian/Ubuntu：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dpkg --add-architecture i386</span></span>
<span class="line"><span>$ sudo apt install zenity wine winetricks libimage-exiftool-perl icoutils gnome-terminal</span></span></code></pre></div><p>Fedora：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install zenity wine winetricks perl-Image-ExifTool icoutils gnome-terminal</span></span></code></pre></div>`,6)),t("p",null,[n[11]||(n[11]=i("官方推荐的安装 WineZGUI 的方法是使用 ")),s(e,{href:"https://ostechnix.com/how-to-install-and-use-flatpak-in-linux/"},{default:p(()=>n[10]||(n[10]=[i("Flatpak")])),_:1}),n[12]||(n[12]=i("。"))]),n[34]||(n[34]=l('<p>安装完 Flatpak 后，逐一运行以下命令，在 Linux 中安装 WineZGUI。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ flatpak --user remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ flatpak --user -y install flathub org.winehq.Wine/x86_64/stable-21.08</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wget https://github.com/fastrizwaan/WineZGUI-Releases/releases/download/WineZGUI-0.4_20220608/io.github.WineZGUI_0_4_20220608.flatpak</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ flatpak --user -y install io.github.WineZGUI_0_4_20220608.flatpak</span></span></code></pre></div><h3 id="在-linux-中用-winezgui-运行-windows-应用和游戏" tabindex="-1">在 Linux 中用 WineZGUI 运行 Windows 应用和游戏 <a class="header-anchor" href="#在-linux-中用-winezgui-运行-windows-应用和游戏" aria-label="Permalink to 在 Linux 中用 WineZGUI 运行 Windows 应用和游戏">​</a></h3><p>从 Dash 或菜单中启动 WineZGUI。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/Launch-WineZGUI.png" alt="Launch WineZGUI"></p><p>这就是 WineZGUI 的默认界面的样子。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/WineZGUI-Interface.png" alt="WineZGUI Interface"></p><p>正如你在上面的截图中看到的，WineZGUI 的界面非常简单易懂。从主窗口中，你可以：</p><ul><li>打开一个 EXE 文件。</li><li>打开 Winetricks GUI 和 CLI。</li><li>启动 Wine 配置。</li><li>启动资源管理器。</li><li>打开 BASH Shell。</li><li>关闭所有的应用/游戏，包括 WineZGUI 界面。</li><li>删除 Wine 前缀。</li><li>查看已安装的 WineZGUI 版本。</li></ul><p>为了演示，我将打开一个 EXE 文件。</p><p>在下一个窗口中，选择要运行的 EXE 文件。在我的例子中，它是 WinRAR。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/Choose-The-EXE-File-To-Run.png" alt="Choose The EXE File To Run"></p><p>接下来，你是想用默认的前缀运行 EXE 文件，还是创建一个新的前缀。我选择默认的前缀。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/Run-WinRAR-With-Default-Prefix.png" alt="Run WinRAR With Default Prefix"></p><p>几秒钟后，会出现 WinRAR 安装向导。点击安装，继续。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/Install-WinRAR-In-Linux.png" alt="Install WinRAR In Linux"></p><p>点击 “OK” 来完成 WinRAR 的安装。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/Complete-WinRAR-Installation.png" alt="Complete WinRAR Installation"></p><p>点击 “<ruby>运行 WinRAR<rt>Run WinRAR</rt></ruby>” 来启动它。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/Run-WinRAR.png" alt="Run WinRAR"></p><p>下面是 WinRAR 在我的 Fedora 36 桌面上的运行情况!</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/06/WinRAR-Is-Running-In-Fedora-Using-Wine.png" alt="WinRAR Is Running In Fedora Using Wine"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>WineZGUI 是俱乐部的新人。如果你正在寻找一种在 Linux 桌面上使用 Wine 运行 Windows 应用和游戏的更简单方法，WineZGUI 可能是一个不错的选择。</p><p>在 WineZGUI 的帮助下，用户可以选择在与 EXE 相同的文件夹中创建一个 Wine 前缀，并创建一个相对链接的 <code>.desktop</code> 条目来自动执行此操作。</p><p>原因是使用 Wine 前缀备份和删除游戏更容易，并且让它生成一个 <code>.desktop</code> 将使其能够适应移动和转移。</p><p>一个很酷的场景是使用该应用进行设置，然后将 Wine 前缀分享给你的朋友和其他人，他们只需要一个具有所有依赖性和保存的工作 Wine 前缀。</p><p>请试一试它，在下面的评论区告诉我们你对这个项目的看法。</p><p><strong>资源：</strong></p>',32)),t("ul",null,[t("li",null,[s(e,{href:"https://github.com/fastrizwaan/WineZGUI"},{default:p(()=>n[13]||(n[13]=[i("WineZGUI GitHub 仓库")])),_:1})])]),n[35]||(n[35]=t("hr",null,null,-1)),t("p",null,[n[15]||(n[15]=i("via: ")),s(e,{href:"https://ostechnix.com/winezgui-run-windows-apps-and-games-on-linux/"},{default:p(()=>n[14]||(n[14]=[i("https://ostechnix.com/winezgui-run-windows-apps-and-games-on-linux/")])),_:1})]),t("p",null,[n[20]||(n[20]=i("作者：")),s(e,{href:"https://ostechnix.com/author/sk/"},{default:p(()=>n[16]||(n[16]=[i("sk")])),_:1}),n[21]||(n[21]=i(" 选题：")),s(e,{href:"https://github.com/lkxed"},{default:p(()=>n[17]||(n[17]=[i("lkxed")])),_:1}),n[22]||(n[22]=i(" 译者：")),s(e,{href:"https://github.com/geekpi"},{default:p(()=>n[18]||(n[18]=[i("geekpi")])),_:1}),n[23]||(n[23]=i(" 校对：")),s(e,{href:"https://github.com/wxy"},{default:p(()=>n[19]||(n[19]=[i("wxy")])),_:1})]),t("p",null,[n[26]||(n[26]=i("本文由 ")),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>n[24]||(n[24]=[i("LCTT")])),_:1}),n[27]||(n[27]=i(" 原创编译，")),s(e,{href:"https://linux.cn/"},{default:p(()=>n[25]||(n[25]=[i("Linux中国")])),_:1}),n[28]||(n[28]=i(" 荣誉推出"))])])}const U=a(r,[["render",g]]);export{f as __pageData,U as default};
